begin;
create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
insert into auth.users(id,email) values('41000000-0000-4000-8000-000000000001','message-a@mizyun.test'),('41000000-0000-4000-8000-000000000002','message-b@mizyun.test'),('41000000-0000-4000-8000-000000000003','message-c@mizyun.test');
update public.profiles set birth_year=1990 where id::text like '41000000%';
create temporary table message_safety_state(message uuid primary key,receipt uuid,report uuid);
grant all on message_safety_state to authenticated;
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000001';
select * from public.community_save_profile('message_a','A','AA',null,true,true,'2026-09-30');
select throws_ok($$select * from public.community_messaging_rpc('preferences','{"enabled":true}')$$,'P0001','community_unavailable','Feature starts closed even for active members');
reset role;update public.community_feature_controls set enabled=true where feature='messaging';
set local role authenticated;set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000001';
select is((select result->>'enabled' from public.community_messaging_rpc('preferences','{"enabled":true}')),'true','Sender deliberately opts in');
set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000002';select * from public.community_save_profile('message_b','B','BB',null,true,true,'2026-09-30');select * from public.community_messaging_rpc('preferences','{"enabled":true}');
set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000003';select * from public.community_save_profile('message_c','C','CC',null,true,true,'2026-09-30');
reset role;set local request.jwt.claim.role='service_role';insert into public.community_relationships(follower_user_id,target_user_id,status) values('41000000-0000-4000-8000-000000000001','41000000-0000-4000-8000-000000000002','approved');
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000001';
select throws_ok($$select * from public.community_messaging_rpc('send','{"id":"42000000-0000-4000-8000-000000000001","peerId":"41000000-0000-4000-8000-000000000002","text":"Hello"}')$$,'P0001','community_unavailable','One-way approval cannot deliver');
reset role;set local request.jwt.claim.role='service_role';insert into public.community_relationships(follower_user_id,target_user_id,status) values('41000000-0000-4000-8000-000000000002','41000000-0000-4000-8000-000000000001','approved');
set local role authenticated;set local request.jwt.claim.role='authenticated';
select is((select result->'message'->>'text' from public.community_messaging_rpc('send','{"id":"42000000-0000-4000-8000-000000000001","peerId":"41000000-0000-4000-8000-000000000002","text":"Hello"}')),'Hello','Mutual consenting friends can send');
select lives_ok($$select * from public.community_messaging_rpc('send','{"id":"42000000-0000-4000-8000-000000000001","peerId":"41000000-0000-4000-8000-000000000002","text":"Hello"}')$$,'Lost-response same-ID replay succeeds');
select is((select count(*) from public.community_messages),1::bigint,'Retry cannot duplicate message');
select throws_ok($$select * from public.community_messaging_rpc('send','{"id":"42000000-0000-4000-8000-000000000001","peerId":"41000000-0000-4000-8000-000000000002","text":"Changed retry"}')$$,'P0001','community_conflict','Conflicting same-ID replay fails');
select throws_ok($$select * from public.community_messaging_rpc('send','{"id":"42000000-0000-4000-8000-000000000002","peerId":"41000000-0000-4000-8000-000000000002","text":"https://example.com"}')$$,'P0001','community_invalid_input','Raw RPC blocks links');
select throws_ok($$select * from public.community_messaging_rpc('edit','{"id":"42000000-0000-4000-8000-000000000001","text":"Missing CAS version"}')$$,'P0001','community_conflict','Omitted edit version cannot bypass compare-and-set');
select throws_ok($$select * from public.community_messaging_rpc('edit','{"id":"42000000-0000-4000-8000-000000000001","version":null,"text":"Null CAS version"}')$$,'P0001','community_conflict','Null edit version cannot bypass compare-and-set');
set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000003';select is((select count(*) from public.community_messages),0::bigint,'Unrelated direct database reads denied');
select throws_ok($$select * from public.community_messaging_rpc('list','{"peerId":"41000000-0000-4000-8000-000000000001"}')$$,'P0001','community_unavailable','Unrelated guessed thread denied');
set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000002';
select is((select jsonb_array_length(result->'messages') from public.community_messaging_rpc('list','{"peerId":"41000000-0000-4000-8000-000000000001"}')),1,'Recipient sees message');
insert into message_safety_state(message,receipt) select '42000000-0000-4000-8000-000000000001',id from public.community_report_receipts_for_caller() where target_type='message' and target_id='42000000-0000-4000-8000-000000000001';
select is((select count(*) from message_safety_state),1::bigint,'Actual received-message page automatically captures exact reporting authority');
select is((select id from public.community_issue_report_receipt('message','42000000-0000-4000-8000-000000000001')),(select receipt from message_safety_state),'Explicit receipt retry returns existing delivery receipt');
select lives_ok($$select * from public.community_messaging_rpc('list','{"peerId":"41000000-0000-4000-8000-000000000001"}')$$,'Repeated delivered page is safe');
select is((select count(*) from public.community_report_receipts_for_caller() where target_type='message'),1::bigint,'Repeated view does not multiply exact evidence receipts');
select throws_ok($$select * from public.community_messaging_rpc('edit','{"id":"42000000-0000-4000-8000-000000000001","version":1,"text":"Forged"}')$$,'P0001','community_unavailable','Recipient cannot edit sender text');
select is((select count(*) from public.community_export_page('messages')),0::bigint,'Export excludes another participant authored text');
select lives_ok($$select * from public.community_issue_report_receipt('message','42000000-0000-4000-8000-000000000001')$$,'Only visible received message can create report evidence');
set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000001';
select * from public.community_messaging_rpc('send','{"id":"42000000-0000-4000-8000-000000000002","peerId":"41000000-0000-4000-8000-000000000002","text":"Second message"}');
select * from public.community_messaging_rpc('delete','{"id":"42000000-0000-4000-8000-000000000001"}');
set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000002';
update message_safety_state set report=(select id from public.community_submit_report('message',message::text,'harassment','Seen before sender removal',receipt)) where message='42000000-0000-4000-8000-000000000001';
select ok((select report is not null from message_safety_state where message='42000000-0000-4000-8000-000000000001'),'View then sender deletion still permits exact receipt-backed report');
select is((select id from public.community_submit_report('message','42000000-0000-4000-8000-000000000001','harassment','Additional context',(select receipt from message_safety_state where message='42000000-0000-4000-8000-000000000001'))),(select report from message_safety_state where message='42000000-0000-4000-8000-000000000001'),'Repeated lost report response returns the same case');
select throws_ok($$select * from public.community_submit_report('message','42000000-0000-4000-8000-000000000001','harassment',null,'42000000-0000-4000-8000-000000000099')$$,'P0001','community_unavailable','Forged explicit receipt cannot bypass validation on case replay');
select * from public.community_messaging_rpc('list','{"peerId":"41000000-0000-4000-8000-000000000001"}');
insert into message_safety_state(message,receipt) select '42000000-0000-4000-8000-000000000002',id from public.community_report_receipts_for_caller() where target_type='message' and target_id='42000000-0000-4000-8000-000000000002';
select * from public.community_messaging_rpc('preferences','{"enabled":false}');
set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000001';
select throws_ok($$select * from public.community_messaging_rpc('send','{"id":"42000000-0000-4000-8000-000000000002","peerId":"41000000-0000-4000-8000-000000000002","text":"After opt-out"}')$$,'P0001','community_unavailable','Recipient opt-out denies new delivery');
reset role;update public.community_feature_controls set enabled=false where feature='messaging';set local role authenticated;
select lives_ok($$select * from public.community_messaging_rpc('delete','{"id":"42000000-0000-4000-8000-000000000001"}')$$,'Privacy delete works with switch off');
select is((select count(*) from public.community_export_page('messages') where item->>'id'='42000000-0000-4000-8000-000000000001' and item->>'text' is not null),0::bigint,'Deletion removes authored text from export');
set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000002';
insert into public.community_blocks(blocker_user_id,blocked_user_id) values(auth.uid(),'41000000-0000-4000-8000-000000000001');
select throws_ok($$select * from public.community_messaging_rpc('list','{"peerId":"41000000-0000-4000-8000-000000000001"}')$$,'P0001','community_unavailable','Blocked conversation cannot be reloaded');
update message_safety_state set report=(select id from public.community_submit_report('message',message::text,'spam',null,receipt)) where message='42000000-0000-4000-8000-000000000002';
select ok((select report is not null from message_safety_state where message='42000000-0000-4000-8000-000000000002'),'View then block and feature freeze retains only exact reporting authority');
select is((select id from public.community_submit_report('message','42000000-0000-4000-8000-000000000002','spam',null,(select receipt from message_safety_state where message='42000000-0000-4000-8000-000000000002'))),(select report from message_safety_state where message='42000000-0000-4000-8000-000000000002'),'Blocked report retries reuse existing case');
set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000003';
select throws_ok($$select * from public.community_submit_report('message','42000000-0000-4000-8000-000000000002','spam',null,(select receipt from message_safety_state where message='42000000-0000-4000-8000-000000000002'))$$,'P0001','community_unavailable','Unrelated member cannot use a stolen delivery receipt');
reset role;
select is((select count(*) from public.community_reports where reporter_user_id='41000000-0000-4000-8000-000000000002' and target_type='message'),2::bigint,'Repeated reports produce exactly one case per received target');
select is((select report_count from public.community_report_usage where user_id='41000000-0000-4000-8000-000000000002' and report_date=(now() at time zone 'UTC')::date),2,'Repeated reports consume exactly two quota units');
select is((select evidence_snapshot->>'text' from public.community_reports where target_type='message' and target_id='42000000-0000-4000-8000-000000000001'),'Hello','Staff evidence contains the specifically delivered text before removal');
update public.community_report_receipts set expires_at=now()-interval '1 second' where id=(select receipt from message_safety_state where message='42000000-0000-4000-8000-000000000001');
set local role authenticated;set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000002';
select throws_ok($$select * from public.community_submit_report('message','42000000-0000-4000-8000-000000000001','harassment',null,(select receipt from message_safety_state where message='42000000-0000-4000-8000-000000000001'))$$,'P0001','community_unavailable','Expired exact receipt cannot reuse an existing case');
reset role;
set local request.jwt.claim.role='service_role';
delete from public.community_messages where id='42000000-0000-4000-8000-000000000001';
select is((select count(*) from public.community_message_operations where id='42000000-0000-4000-8000-000000000001'),1::bigint,'Physical content purge retains no-text operation tombstone');
update public.community_feature_controls set enabled=true where feature='messaging';
delete from public.community_blocks where blocker_user_id='41000000-0000-4000-8000-000000000002';
update public.community_messaging_preferences set enabled=true where user_id in('41000000-0000-4000-8000-000000000001','41000000-0000-4000-8000-000000000002');
insert into public.community_relationships(follower_user_id,target_user_id,status) values('41000000-0000-4000-8000-000000000001','41000000-0000-4000-8000-000000000002','approved'),('41000000-0000-4000-8000-000000000002','41000000-0000-4000-8000-000000000001','approved') on conflict do nothing;
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='41000000-0000-4000-8000-000000000001';
select throws_ok($$select * from public.community_messaging_rpc('send','{"id":"42000000-0000-4000-8000-000000000001","peerId":"41000000-0000-4000-8000-000000000002","text":"Hello"}')$$,'P0001','community_conflict','Old send replay cannot recreate physically purged text');
select * from finish();rollback;
